// GENERATED by tools/sync-scoring.mjs từ packages/data/src/mastery/remediation.ts — KHÔNG sửa tay, sửa file gốc rồi chạy lại.
/**
 * Lập bộ ôn tập (lỗ hổng) và lịch ôn lại (lặp lại ngắt quãng). THUẦN — chép sang Edge Function.
 */
import { MISCONCEPTIONS, SKILL_BY_CODE, type Misconception, type RemediationAnswer, type RemediationSet, type ReviewStage, type Skill, type SkillMastery, type SubjectId } from '../scoring/contracts.ts';
import { MAX_REMEDIATION_SETS, PASS_RATIO, SET_MAX_ITEMS, SET_MIN_ITEMS } from './constants.ts';
import { findGaps } from './gaps.ts';
import { isGradedType, type ItemLike } from './observe.ts';

const DIFFICULTY_RANK: Record<string, number> = { 'nhan-biet': 0, 'ket-noi': 1, 'van-dung': 2 };

export function remediationSetId(userId: string, skillCode: string, stage: number): string {
  return `rem:${userId}:${skillCode}:${stage}`;
}

export function parseRemediationSetId(id: string): { userId: string; skillCode: string; stage: ReviewStage } | null {
  const m = /^rem:(.+):([^:]+):([0-3])$/.exec(id);
  return m ? { userId: m[1], skillCode: m[2], stage: Number(m[3]) as ReviewStage } : null;
}

/** Câu hỏi cho một kĩ năng: có chấm, dễ trước; `offset` xoay vòng để mỗi chặng ôn có câu khác. */
export function itemsForSkill(code: string, items: ItemLike[], offset = 0): string[] {
  const list = items
    .filter((it) => isGradedType(it.type) && (it.skills ?? []).includes(code))
    .sort((a, b) => {
      const pa = (a.skills ?? [])[0] === code ? 0 : 1;
      const pb = (b.skills ?? [])[0] === code ? 0 : 1;
      return (DIFFICULTY_RANK[a.difficulty ?? 'ket-noi'] ?? 1) - (DIFFICULTY_RANK[b.difficulty ?? 'ket-noi'] ?? 1) || pa - pb || a.id.localeCompare(b.id);
    })
    .map((it) => it.id);
  if (!list.length || !offset) return list;
  const k = offset % list.length;
  // Xoay nhưng vẫn giữ thứ tự dễ → khó trong phần được chọn.
  return [...list.slice(k), ...list.slice(0, k)];
}

/**
 * Ghép câu: gốc trước (tối đa 2 nếu gốc ≠ kĩ năng), rồi kĩ năng lỗ hổng; còn thiếu thì lấy thêm từ `fallback`
 * (thường là kĩ năng nền trực tiếp). 3–5 câu, không trùng.
 */
export function pickSetItems(skillCode: string, rootSkill: string, items: ItemLike[], offset = 0, fallback: string[] = []): string[] {
  const out: string[] = [];
  const add = (ids: string[], max: number) => {
    for (const id of ids) {
      if (out.length >= max) break;
      if (!out.includes(id)) out.push(id);
    }
  };
  if (rootSkill !== skillCode) add(itemsForSkill(rootSkill, items, offset), 2);
  add(itemsForSkill(skillCode, items, offset), SET_MAX_ITEMS);
  if (rootSkill !== skillCode && out.length < SET_MAX_ITEMS) add(itemsForSkill(rootSkill, items, offset), SET_MAX_ITEMS);
  for (const f of fallback) {
    if (out.length >= SET_MIN_ITEMS) break;
    add(itemsForSkill(f, items, offset), SET_MIN_ITEMS);
  }
  return out;
}

export function evaluateRemediation(results: RemediationAnswer[]): { correct: number; total: number; passed: boolean } {
  const total = results.length;
  const correct = results.filter((r) => r.correct).length;
  const need = Math.max(1, Math.round(total * PASS_RATIO));
  return { correct, total, passed: total > 0 && correct >= need };
}

function pct(p: number): number {
  return Math.round(p * 100);
}

export interface PlanInput {
  userId: string;
  masteries: SkillMastery[];
  items: ItemLike[];
  now: Date;
  skills?: Record<string, Skill>;
  misconceptions?: Record<string, Misconception>;
  maxSets?: number;
}

/**
 * Bộ ôn tập của HS. Thứ tự: ôn lại ĐẾN HẠN (sớm trước) → lỗ hổng mới (ưu tiên cao trước, tối đa 3, mỗi gốc một bộ)
 * → ôn lại CHƯA đến hạn. Bỏ bộ có < 3 câu.
 */
export function planRemediation(input: PlanInput): RemediationSet[] {
  const skills = input.skills ?? SKILL_BY_CODE;
  const mis = input.misconceptions ?? MISCONCEPTIONS;
  const nowIso = input.now.toISOString();
  const short = (c: string) => skills[c]?.short ?? c;
  const subjectOf = (c: string): SubjectId => skills[c]?.subject ?? 'toan';
  const minutes = (n: number) => Math.max(2, Math.ceil(n * 0.6));

  const reviews: RemediationSet[] = [];
  for (const m of input.masteries) {
    if (m.reviewStage === 0 || !m.nextReviewAt || m.level === 'can-on') continue;
    const itemIds = pickSetItems(m.skillCode, m.skillCode, input.items, m.reviewStage * 2, skills[m.skillCode]?.prereqs ?? []);
    if (itemIds.length < SET_MIN_ITEMS) continue;
    reviews.push({
      id: remediationSetId(input.userId, m.skillCode, m.reviewStage),
      userId: input.userId,
      kind: 'review',
      skillCode: m.skillCode,
      rootSkill: m.skillCode,
      subject: subjectOf(m.skillCode),
      title: `Ôn nhanh: ${short(m.skillCode)}`,
      reason: `Ôn lại lần ${m.reviewStage} theo lịch (sau 1, 3, 7 ngày) để nhớ lâu “${short(m.skillCode)}”.`,
      itemIds,
      reviewStage: m.reviewStage,
      dueAt: m.nextReviewAt,
      minutes: minutes(itemIds.length),
    });
  }

  const gapSets: RemediationSet[] = [];
  const usedRoots = new Set<string>();
  for (const g of findGaps(input.masteries, skills, mis)) {
    if (gapSets.length >= (input.maxSets ?? MAX_REMEDIATION_SETS)) break;
    if (usedRoots.has(g.rootSkill)) continue;
    const itemIds = pickSetItems(g.skillCode, g.rootSkill, input.items, 0, [...(skills[g.rootSkill]?.prereqs ?? []), ...(skills[g.skillCode]?.prereqs ?? [])]);
    if (itemIds.length < SET_MIN_ITEMS) continue;
    usedRoots.add(g.rootSkill);
    const mc = g.topMisconceptions[0];
    const rootPart = g.rootSkill !== g.skillCode ? ` Gốc có thể ở kĩ năng nền “${short(g.rootSkill)}”.` : '';
    gapSets.push({
      id: remediationSetId(input.userId, g.skillCode, 0),
      userId: input.userId,
      kind: 'remediation',
      skillCode: g.skillCode,
      rootSkill: g.rootSkill,
      subject: subjectOf(g.skillCode),
      title: `Ôn lại: ${short(g.rootSkill)}`,
      reason: `Chưa vững “${short(g.skillCode)}” (đúng khoảng ${pct(g.p)}% trong ${g.attempts} câu gần đây).${rootPart}${mc ? ` Hay mắc: ${mc.text.charAt(0).toLowerCase()}${mc.text.slice(1)}` : ''}`,
      itemIds,
      reviewStage: 0,
      dueAt: nowIso,
      minutes: minutes(itemIds.length),
    });
  }

  const t = input.now.getTime();
  const due = reviews.filter((r) => new Date(r.dueAt).getTime() <= t).sort((a, b) => a.dueAt.localeCompare(b.dueAt));
  const later = reviews.filter((r) => new Date(r.dueAt).getTime() > t).sort((a, b) => a.dueAt.localeCompare(b.dueAt));
  return [...due, ...gapSets, ...later];
}

/** Lời nhắn cho HS sau bộ ôn tập. */
export function remediationMessage(passed: boolean, stage: ReviewStage, correct: number, total: number): string {
  if (!passed) return `Em đúng ${correct}/${total} câu. Mình cùng ôn lại thêm một chút nữa nhé, em sẽ làm được!`;
  if (stage >= 3) return `Tuyệt vời! Em đúng ${correct}/${total} câu và đã ôn đủ 3 chặng. Kĩ năng này em nắm chắc rồi!`;
  const days = [1, 3, 7][Math.max(0, stage - 1)];
  return `Giỏi lắm! Em đúng ${correct}/${total} câu. ${days} ngày nữa mình ôn nhanh lại một lần để nhớ thật lâu nhé!`;
}
